<?php declare(strict_types=1);require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('PUT','POST');apiCsrf();$uid=apiAuth();$in=apiInput();$id=apiId($in['id']??0);$status=(string)($in['status']??'');if(!in_array($status,['open','accepted','rejected','closed'],true))apiError('Invalid status',422);$s=apiDb()->prepare('UPDATE negotiations n JOIN quotation_requests q ON q.id=n.quotation_request_id SET n.status=? WHERE n.id=? AND q.buyer_id=?');$s->execute([$status,$id,$uid]);if(!$s->rowCount())apiError('Negotiation not found',404);apiResponse(['id'=>$id,'status'=>$status]);